<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, shallowRef } from 'vue'
import type * as Monaco from 'monaco-editor/esm/vs/editor/editor.api'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Close, MoreFilled, Plus, Search } from '@element-plus/icons-vue'
import { dataSourceApi } from '../../api/platform'
import { developmentApi, metadataApi, releaseApi, type DataSourceView, type DevFile, type DevFolder, type DevProject, type RecycledDevFile, type DevelopmentBundle, type DevelopmentBundleRelease, type DevelopmentSchedule, type LineageView, type QueryResult } from '../../api/domain'

type DockPane='property'|'schedule'|'version'
type BottomPane='result'|'log'|'plan'|'lineage'|'scheduleDag'
type ResourceTarget={kind:'file'|'folder';id:number;name:string;folderId?:number;parentId?:number}
type TreeRow={kind:'file'|'folder';id:number;name:string;depth:number;file?:DevFile;folder?:DevFolder}
type DevSession={content:string;dirty:boolean;sourceId?:number;database:string;activeBottom:BottomPane;activeDock:DockPane|null;result?:QueryResult;logText:string;planText:string;lineage:LineageView[];schedule?:DevelopmentSchedule;bundle?:DevelopmentBundle;releases:DevelopmentBundleRelease[];propertyDescription:string;scheduleForm:Record<string,any>;running:boolean}

const projects=ref<DevProject[]>([]),folders=ref<DevFolder[]>([]),files=ref<DevFile[]>([]),recycledFiles=ref<RecycledDevFile[]>([]),sources=ref<DataSourceView[]>([]),databases=ref<string[]>([])
const projectId=ref<number>(),file=ref<DevFile>(),openFiles=ref<DevFile[]>([]),sourceId=ref<number>(),database=ref('')
const editorHost=ref<HTMLElement>(),editor=shallowRef<Monaco.editor.IStandaloneCodeEditor>(),editorLoading=ref(false),running=ref(false),saving=ref(false)
const codeDirty=ref(false),treeSearch=ref(''),groupMode=ref<'all'|'recent'|'mine'>('all'),activeBottom=ref<BottomPane>('result'),activeDock=ref<DockPane|null>(null)
const result=ref<QueryResult>(),logText=ref('暂无执行日志'),planText=ref('运行 SQL 后查看执行计划'),lineage=ref<LineageView[]>([])
const schedule=ref<DevelopmentSchedule>(),bundle=ref<DevelopmentBundle>(),releases=ref<DevelopmentBundleRelease[]>([])
const scheduleSaving=ref(false),publishOpen=ref(false),releaseDetailOpen=ref(false),selectedRelease=ref<DevelopmentBundleRelease>()
const compareOpen=ref(false),compareLoading=ref(false),compareTab=ref<'code'|'schedule'>('code'),compareSqlCurrent=ref(''),compareSqlOnline=ref(''),compareScheduleCurrent=ref<DevelopmentSchedule>(),compareScheduleOnline=ref<DevelopmentSchedule>(),compareEditorHost=ref<HTMLElement>()
const compareDiffEditor=shallowRef<Monaco.editor.IStandaloneDiffEditor>();let compareOriginalModel:Monaco.editor.ITextModel|undefined,compareModifiedModel:Monaco.editor.ITextModel|undefined
const expandedFolders=ref<Set<number>>(new Set())
const newFolderOpen=ref(false),newFolder=reactive({name:'',parentId:undefined as number|undefined})
const newTaskOpen=ref(false),newTask=reactive({name:'',type:'SQL',folderId:undefined as number|undefined,description:'',configureSchedule:false})
const moveOpen=ref(false),moveTarget=ref<ResourceTarget>(),moveFolderId=ref<number|undefined>(),recycleOpen=ref(false)
const saveDraftOpen=ref(false),saveDraft=reactive({name:'',folderId:undefined as number|undefined})
const publishRemark=ref('统一发布代码与调度配置')
const propertyDescription=ref('')
const scheduleForm=reactive({enabled:false,cycleType:'DAILY',executionTime:'02:00',hourMinute:0,cronExpression:'0 0 2 * * ?',timezone:'Asia/Shanghai',dataSourceId:undefined as number|undefined,databaseName:'',bizDateParam:'${system.biz.date-1}',retryTimes:3,retryIntervalMinutes:5,timeoutMinutes:120,upstreamFileIds:[] as number[]})
let monacoApi:typeof import('monaco-editor/esm/vs/editor/editor.api')|null=null
let applyingContent=false
let tempFileSeq=-1
let tempNameSeq=1
const sessions=reactive(new Map<number,DevSession>())

const currentName=computed(()=>stripExt(file.value?.name||'未打开任务'))
const currentType=computed(()=>file.value?.fileType?.toUpperCase()||'SQL')
const currentTypeLabel=computed(()=>({SQL:'SQL',SHELL:'Shell',PYTHON:'Python'} as Record<string,string>)[currentType.value]||currentType.value)
const isSql=computed(()=>currentType.value==='SQL')
const unsaved=computed(()=>Boolean(codeDirty.value||bundle.value?.sqlDirty||bundle.value?.scheduleDirty))
const currentSourceName=computed(()=>sources.value.find(x=>x.id===sourceId.value)?.name||'未选择 StarRocks')
const publishedCode=computed(()=>bundle.value?.publishedSqlVersion||0)
const publishedSchedule=computed(()=>bundle.value?.publishedScheduleVersion||0)
const onlineRelease=computed(()=>releases.value.find(x=>x.current))
const minuteOptions=Array.from({length:60},(_,i)=>i)
const compareSqlChanged=computed(()=>compareSqlCurrent.value.trimEnd()!==compareSqlOnline.value.trimEnd())
const compareScheduleRows=computed(()=>{const a=compareScheduleCurrent.value,b=compareScheduleOnline.value;const dep=(x?:DevelopmentSchedule)=>(x?.dependencies||[]).map(d=>d.name).sort().join('、')||'—';const source=(id?:number)=>sources.value.find(x=>x.id===id)?.name||(id?`#${id}`:'—');const time=(x?:DevelopmentSchedule)=>x?.cycleType==='HOURLY'?`每小时第 ${Number((x.cronExpression||'').split(/\s+/)[1]||0)} 分钟`:x?.executionTime||'—';const rows=[['状态',a?.enabled?'已启用':'已停用',b?.enabled?'已启用':'已停用'],['周期',cycleLabel(a?.cycleType||'DAILY'),cycleLabel(b?.cycleType||'DAILY')],['执行时间',time(a),time(b)],['Cron',a?.cronExpression||'—',b?.cronExpression||'—'],['数据源',source(a?.dataSourceId),source(b?.dataSourceId)],['Database',a?.databaseName||'—',b?.databaseName||'—'],['上游依赖',dep(a),dep(b)],['biz_date',a?.bizDateParam||'—',b?.bizDateParam||'—'],['失败重试',`${a?.retryTimes??0} 次 / ${a?.retryIntervalMinutes??0} 分钟`,`${b?.retryTimes??0} 次 / ${b?.retryIntervalMinutes??0} 分钟`],['超时',`${a?.timeoutMinutes??0} 分钟`,`${b?.timeoutMinutes??0} 分钟`]];return rows.map(([name,current,online])=>({name,current,online,changed:current!==online}))})
const scheduleDependencies=computed(()=>schedule.value?.dependencies||[])
const scheduleDownstream=computed(()=>schedule.value?.downstream||[])
const upstreamOptions=computed(()=>files.value.filter(x=>x.id!==file.value?.id&&x.fileType?.toUpperCase()==='SQL'))
const folderOptions=computed(()=>folders.value.map(f=>({id:f.id,label:folderPath(f)})).sort((a,b)=>a.label.localeCompare(b.label,'zh-CN')))
const moveFolderOptions=computed(()=>folderOptions.value.filter(x=>!(moveTarget.value?.kind==='folder'&&x.id===moveTarget.value.id)))
function fileDeleteProtected(f?:DevFile){return Boolean(f&&(f.status==='PUBLISHED'||(f.id===file.value?.id&&(bundle.value?.releaseNo||0)>0)))}

function stripExt(v:string){return v.replace(/\.(sql|sh|py)$/i,'')}
function fileTypeText(v?:string){return ({SQL:'SQL',SHELL:'SH',PYTHON:'PY'} as Record<string,string>)[(v||'SQL').toUpperCase()]||'TXT'}
function extensionOf(v:string){return v==='SHELL'?'.sh':v==='PYTHON'?'.py':'.sql'}
function languageOf(v?:string){return v?.toUpperCase()==='PYTHON'?'python':v?.toUpperCase()==='SHELL'?'shell':'sql'}
function defaultContent(type:string,name:string){if(type==='SHELL')return `#!/bin/bash\n# ${name}\n\necho "DataSphere task: ${name}"\n`;if(type==='PYTHON')return `# ${name}\n\ndef main():\n    print("DataSphere task: ${name}")\n\nif __name__ == "__main__":\n    main()\n`;return `-- ${name}\n\nSELECT\n    *\nFROM \nWHERE 1 = 1;`}
function msg(e:unknown){return e instanceof Error?e.message:'操作失败'}
function fmt(v?:string){return v?v.replace('T',' ').slice(0,19):'—'}
function cycleLabel(v:string){return ({DAILY:'每日',HOURLY:'每小时',WEEKLY:'每周',MONTHLY:'每月',CRON:'自定义 Cron'} as Record<string,string>)[v]||v}
function stateClass(f:DevFile){if(sessionDirty(f.id)||(f.id===file.value?.id&&codeDirty.value))return'dirty';return f.status==='PUBLISHED'?'ok':'dirty'}
function folderPath(folder:DevFolder){const names=[folder.name];let p=folder.parentId;const seen=new Set<number>();while(p&& !seen.has(p)){seen.add(p);const parent=folders.value.find(x=>x.id===p);if(!parent)break;names.unshift(parent.name);p=parent.parentId}return names.join(' / ')}
function folderExpanded(id:number){return Boolean(treeSearch.value.trim())||expandedFolders.value.has(id)}
function toggleFolder(id:number){const next=new Set(expandedFolders.value);next.has(id)?next.delete(id):next.add(id);expandedFolders.value=next}
function fileVisible(f:DevFile){if(groupMode.value==='recent'&&!openFiles.value.some(x=>x.id===f.id))return false;const q=treeSearch.value.trim().toLowerCase();return !q||f.name.toLowerCase().includes(q)}
function folderMatches(folder:DevFolder):boolean{const q=treeSearch.value.trim().toLowerCase();if(!q)return true;if(folder.name.toLowerCase().includes(q))return true;if(files.value.some(f=>f.folderId===folder.id&&f.name.toLowerCase().includes(q)))return true;return folders.value.filter(x=>x.parentId===folder.id).some(folderMatches)}
const treeRows=computed<TreeRow[]>(()=>{const out:TreeRow[]=[];const walk=(parentId:number|undefined,depth:number)=>{const fs=folders.value.filter(x=>(x.parentId??undefined)===parentId).sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'));for(const folder of fs){if(!folderMatches(folder))continue;out.push({kind:'folder',id:folder.id,name:folder.name,depth,folder});if(folderExpanded(folder.id))walk(folder.id,depth+1)}const direct=files.value.filter(x=>(x.folderId??undefined)===parentId&&fileVisible(x)).sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'));for(const f of direct)out.push({kind:'file',id:f.id,name:f.name,depth,file:f})};walk(undefined,0);return out})

function sessionDirty(id:number){return sessions.get(id)?.dirty||false}
function scheduleFormSnapshot(){return {...scheduleForm,upstreamFileIds:[...scheduleForm.upstreamFileIds]}}
function ensureSession(row:DevFile){let s=sessions.get(row.id);if(!s){s={content:row.content||'',dirty:false,sourceId:sourceId.value,database:database.value,activeBottom:'result',activeDock:null,result:undefined,logText:'暂无执行日志',planText:'运行 SQL 后查看执行计划',lineage:[],schedule:undefined,bundle:undefined,releases:[],propertyDescription:row.description||'',scheduleForm:scheduleFormSnapshot(),running:false};sessions.set(row.id,s)}return s}
function saveCurrentSession(){const current=file.value;if(!current)return;const s=ensureSession(current);if(editor.value)s.content=editor.value.getValue();s.dirty=codeDirty.value;s.sourceId=sourceId.value;s.database=database.value;s.activeBottom=activeBottom.value;s.activeDock=activeDock.value;s.result=result.value;s.logText=logText.value;s.planText=planText.value;s.lineage=[...lineage.value];s.schedule=schedule.value;s.bundle=bundle.value;s.releases=[...releases.value];s.propertyDescription=propertyDescription.value;s.scheduleForm=scheduleFormSnapshot();s.running=running.value}
async function restoreSession(row:DevFile){const s=ensureSession(row);sourceId.value=s.sourceId;database.value=s.database;activeBottom.value=s.activeBottom;activeDock.value=s.activeDock;result.value=s.result;logText.value=s.logText;planText.value=s.planText;lineage.value=[...s.lineage];schedule.value=s.schedule;bundle.value=s.bundle;releases.value=[...s.releases];propertyDescription.value=s.propertyDescription;Object.assign(scheduleForm,s.scheduleForm,{upstreamFileIds:[...(s.scheduleForm.upstreamFileIds||[])]});running.value=s.running;setEditorContent(s.content,row.fileType,s.dirty);if(sourceId.value)await loadDatabases();if(s.database&&databases.value.includes(s.database))database.value=s.database}
async function initEditor(){if(!editorHost.value||editor.value||editorLoading.value)return;editorLoading.value=true;try{monacoApi??=await import('monaco-editor/esm/vs/editor/editor.api');await Promise.all([import('monaco-editor/esm/vs/basic-languages/sql/sql.contribution'),import('monaco-editor/esm/vs/basic-languages/python/python.contribution'),import('monaco-editor/esm/vs/basic-languages/shell/shell.contribution')]);if(!editorHost.value)return;editor.value=monacoApi.editor.create(editorHost.value,{value:file.value?.content||'// 请选择开发任务',language:languageOf(file.value?.fileType),theme:'vs',automaticLayout:true,minimap:{enabled:false},fontSize:13,lineHeight:24,scrollBeyondLastLine:false,padding:{top:14},renderLineHighlight:'line'});editor.value.addCommand(monacoApi.KeyMod.CtrlCmd|monacoApi.KeyCode.Enter,()=>void runCode());editor.value.addCommand(monacoApi.KeyMod.CtrlCmd|monacoApi.KeyCode.KeyS,()=>void saveCode());editor.value.onDidChangeModelContent(()=>{if(!applyingContent)codeDirty.value=true})}catch(e){ElMessage.error('编辑器加载失败：'+msg(e))}finally{editorLoading.value=false}}
function setEditorContent(v:string,type?:string,dirty=false){if(!editor.value)return;applyingContent=true;editor.value.setValue(v||'');const model=editor.value.getModel();if(model&&monacoApi)monacoApi.editor.setModelLanguage(model,languageOf(type));codeDirty.value=dirty;queueMicrotask(()=>applyingContent=false)}

async function boot(){try{const [ps,ds]=await Promise.all([developmentApi.projects(),dataSourceApi.list()]);projects.value=ps;sources.value=ds.filter(x=>x.type==='STARROCKS');projectId.value=ps[0]?.id;sourceId.value=sources.value[0]?.id;if(sourceId.value)await loadDatabases();if(projectId.value)await loadResources();await nextTick();void initEditor()}catch(e){ElMessage.error(msg(e))}}
async function loadResources(preferred?:number){if(!projectId.value)return;const [fd,fl,rc]=await Promise.all([developmentApi.folders(projectId.value),developmentApi.files(projectId.value),developmentApi.recycleBin(projectId.value)]);folders.value=fd;files.value=fl;recycledFiles.value=rc;if(!expandedFolders.value.size)expandedFolders.value=new Set(fd.filter(x=>!x.parentId).map(x=>x.id));if(file.value){const fresh=fl.find(x=>x.id===file.value?.id);if(fresh)file.value={...file.value,...fresh}}openFiles.value=openFiles.value.map(x=>fl.find(f=>f.id===x.id)||x);const target=fl.find(x=>x.id===preferred)||(!file.value?fl[0]:undefined);if(target)await openFile(target)}
async function loadDatabases(){if(!sourceId.value)return;const rows=await metadataApi.databases(sourceId.value,'STARROCKS');databases.value=rows.map(x=>x.name);if(!databases.value.includes(database.value))database.value=databases.value[0]||''}
async function openFile(row:DevFile){
  if(file.value?.id===row.id)return
  saveCurrentSession()
  const existing=sessions.get(row.id)
  if(existing){file.value=openFiles.value.find(x=>x.id===row.id)||row;await restoreSession(file.value);return}
  if(row.id<0){file.value=row;ensureSession(row).dirty=true;await restoreSession(row);return}
  const detail=await developmentApi.getFile(row.id);file.value=detail
  const idx=openFiles.value.findIndex(x=>x.id===detail.id);if(idx<0)openFiles.value.push(detail);else openFiles.value[idx]=detail
  ensureSession(detail);await restoreSession(detail);await loadTaskMeta();saveCurrentSession()
}
async function loadTaskMeta(){const current=file.value;if(!current||current.id<0)return;const targetId=current.id,targetSession=ensureSession(current);const [sc,bd,rs]=await Promise.all([developmentApi.schedule(targetId),developmentApi.bundle(targetId),developmentApi.bundleReleases(targetId)]);targetSession.schedule=sc;targetSession.bundle=bd;targetSession.releases=rs;targetSession.sourceId=sc.dataSourceId||targetSession.sourceId;targetSession.database=sc.databaseName||targetSession.database;targetSession.scheduleForm={enabled:sc.enabled,cycleType:sc.cycleType||'DAILY',executionTime:sc.executionTime||'02:00',cronExpression:sc.cronExpression||'0 0 2 * * ?',timezone:sc.timezone||'Asia/Shanghai',dataSourceId:sc.dataSourceId||targetSession.sourceId,databaseName:sc.databaseName||targetSession.database,bizDateParam:sc.bizDateParam||'${system.biz.date-1}',retryTimes:sc.retryTimes??3,retryIntervalMinutes:sc.retryIntervalMinutes??5,timeoutMinutes:sc.timeoutMinutes??120,upstreamFileIds:sc.dependencies.map(x=>x.fileId)};if(file.value?.id===targetId){schedule.value=sc;bundle.value=bd;releases.value=rs;sourceId.value=targetSession.sourceId;database.value=targetSession.database;Object.assign(scheduleForm,targetSession.scheduleForm,{upstreamFileIds:[...targetSession.scheduleForm.upstreamFileIds]});if(sourceId.value)await loadDatabases();if(targetSession.database&&databases.value.includes(targetSession.database))database.value=targetSession.database;if(isSql.value)await loadLineage();else lineage.value=[];saveCurrentSession()}}
function fillSchedule(s:DevelopmentSchedule){const minute=Number((s.cronExpression||'').split(/\s+/)[1]||0);Object.assign(scheduleForm,{enabled:s.enabled,cycleType:s.cycleType||'DAILY',executionTime:s.executionTime||'02:00',hourMinute:Number.isFinite(minute)?minute:0,cronExpression:s.cronExpression||'0 0 2 * * ?',timezone:s.timezone||'Asia/Shanghai',dataSourceId:s.dataSourceId||sourceId.value,databaseName:s.databaseName||database.value,bizDateParam:s.bizDateParam||'${system.biz.date-1}',retryTimes:s.retryTimes??3,retryIntervalMinutes:s.retryIntervalMinutes??5,timeoutMinutes:s.timeoutMinutes??120,upstreamFileIds:s.dependencies.map(x=>x.fileId)})}

async function saveCode(){const current=file.value,ed=editor.value;if(!current||!ed)return;if(current.id<0){current.content=ed.getValue();saveDraft.name=stripExt(current.name);saveDraft.folderId=undefined;saveDraftOpen.value=true;return}saving.value=true;try{const saved=await developmentApi.saveFile(current.id,{content:ed.getValue(),name:current.name,description:current.description});file.value=saved;codeDirty.value=false;const ss=ensureSession(saved);ss.content=ed.getValue();ss.dirty=false;ElMessage.success(`已保存为开发版本 V${saved.currentVersion}，尚未发布`);await refreshBundle(saved.id);saveCurrentSession();await loadResources()}catch(e){ElMessage.error(msg(e))}finally{saving.value=false}}
async function confirmSaveDraft(){const current=file.value,pid=projectId.value;if(!current||current.id>=0||!pid)return;if(!saveDraft.name.trim())return ElMessage.warning('请输入 SQL 文件名称');saving.value=true;try{const tempId=current.id;const name=saveDraft.name.trim().replace(/\.sql$/i,'')+'.sql';const created=await developmentApi.createFile({projectId:pid,folderId:saveDraft.folderId,name,fileType:'SQL',content:editor.value?.getValue()||current.content,description:propertyDescription.value});const oldSession=sessions.get(tempId);sessions.delete(tempId);const idx=openFiles.value.findIndex(x=>x.id===tempId);if(idx>=0)openFiles.value[idx]=created;file.value=created;if(oldSession)sessions.set(created.id,{...oldSession,content:editor.value?.getValue()||current.content,dirty:false});saveDraftOpen.value=false;codeDirty.value=false;if(saveDraft.folderId)expandedFolders.value=new Set([...expandedFolders.value,saveDraft.folderId]);await loadResources(created.id);await loadTaskMeta();saveCurrentSession();ElMessage.success('SQL 已保存并加入开发目录')}catch(e){ElMessage.error(msg(e))}finally{saving.value=false}}
async function newSqlDraft(){const pid=projectId.value;if(!pid)return;saveCurrentSession();const no=tempNameSeq++;const draft:DevFile={id:tempFileSeq--,projectId:pid,name:`未命名${no}.sql`,fileType:'SQL',content:'-- 临时 SQL\n\nSELECT 1;',description:'',status:'DRAFT',currentVersion:0};openFiles.value.push(draft);file.value=draft;const ss=ensureSession(draft);ss.dirty=true;ss.activeDock=null;await restoreSession(draft)}
async function saveProperty(){if(!file.value)return;if(file.value.id<0){file.value.description=propertyDescription.value;return}try{file.value=await developmentApi.saveFile(file.value.id,{content:file.value.content,name:file.value.name,description:propertyDescription.value});await loadResources();ElMessage.success('任务属性已保存')}catch(e){ElMessage.error(msg(e))}}
async function runCode(){const current=file.value,ed=editor.value;if(!current)return;if(!isSql.value)return ElMessage.warning(`${currentTypeLabel.value} 任务执行引擎尚未接入，当前仅支持 SQL 运行`);if(!sourceId.value||!ed)return ElMessage.warning('请选择 StarRocks 数据源');const targetId=current.id,targetSession=ensureSession(current),runSource=sourceId.value,runDatabase=database.value,sql=ed.getModel()?.getValue()||'';targetSession.running=true;targetSession.activeBottom='log';targetSession.logText='正在提交 SQL 到 StarRocks...';running.value=true;activeBottom.value='log';logText.value=targetSession.logText;try{const r=await developmentApi.query(sql,runSource,runDatabase||undefined);targetSession.result=r;targetSession.logText=`[${new Date().toLocaleTimeString()}] 提交 SQL 到 ${sources.value.find(x=>x.id===runSource)?.name||'StarRocks'}\n数据库：${runDatabase||'—'}\n执行成功，返回 ${r.rowCount} 行\n总耗时 ${r.elapsedMs} ms`;targetSession.activeBottom='result';if(file.value?.id===targetId){result.value=r;logText.value=targetSession.logText;activeBottom.value='result'}ElMessage.success('SQL 执行成功')}catch(e){targetSession.logText=msg(e);if(file.value?.id===targetId)logText.value=targetSession.logText;ElMessage.error(msg(e))}finally{targetSession.running=false;if(file.value?.id===targetId)running.value=false}}
async function loadPlan(){const current=file.value,ed=editor.value;if(!current||!isSql.value||!sourceId.value||!ed){planText.value='执行计划仅支持 SQL 任务';return}const targetId=current.id,targetSession=ensureSession(current),src=sourceId.value,db=database.value,sql=ed.getValue();try{const r=await developmentApi.query('EXPLAIN '+sql,src,db||undefined);targetSession.planText=r.rows.map(row=>Object.values(row).join('  ')).join('\n')||'暂无执行计划';if(file.value?.id===targetId)planText.value=targetSession.planText}catch(e){targetSession.planText=msg(e);if(file.value?.id===targetId)planText.value=targetSession.planText}}
function formatCode(){editor.value?.getAction('editor.action.formatDocument')?.run()}
async function refreshBundle(targetId=file.value?.id){if(targetId==null||targetId<0)return;const current=sessions.get(targetId),[bd,rs]=await Promise.all([developmentApi.bundle(targetId),developmentApi.bundleReleases(targetId)]);if(current){current.bundle=bd;current.releases=rs}if(file.value?.id===targetId){bundle.value=bd;releases.value=rs}}
function toggleDock(type:DockPane){if((file.value?.id??0)<0&&type!=='property'){ElMessage.info('请先保存临时 SQL 后再配置调度或查看版本');return}activeDock.value=activeDock.value===type?null:type;if(type==='schedule'&&activeDock.value&&schedule.value)fillSchedule(schedule.value);saveCurrentSession()}
function closeDock(){activeDock.value=null;saveCurrentSession()}
async function onScheduleSourceChange(){sourceId.value=scheduleForm.dataSourceId;await loadDatabases();scheduleForm.databaseName=databases.value[0]||''}
function syncCron(){const t=scheduleForm.executionTime||'02:00',[h,m]=t.split(':').map(Number);if(scheduleForm.cycleType==='DAILY')scheduleForm.cronExpression=`0 ${m||0} ${h||0} * * ?`;else if(scheduleForm.cycleType==='HOURLY')scheduleForm.cronExpression=`0 ${scheduleForm.hourMinute||0} * * * ?`;else if(scheduleForm.cycleType==='WEEKLY')scheduleForm.cronExpression=`0 ${m||0} ${h||0} ? * MON`;else if(scheduleForm.cycleType==='MONTHLY')scheduleForm.cronExpression=`0 ${m||0} ${h||0} 1 * ?`}
async function saveSchedule(){const current=file.value;if(!current)return;if(!isSql.value)return ElMessage.warning('当前仅 SQL 开发任务支持生产调度');if(!scheduleForm.dataSourceId)return ElMessage.warning('请选择 StarRocks 数据源');const targetId=current.id,targetSession=ensureSession(current),payload={enabled:scheduleForm.enabled,cycleType:scheduleForm.cycleType,executionTime:scheduleForm.executionTime,cronExpression:scheduleForm.cronExpression,timezone:scheduleForm.timezone,dataSourceId:scheduleForm.dataSourceId,databaseName:scheduleForm.databaseName,bizDateParam:scheduleForm.bizDateParam,retryTimes:scheduleForm.retryTimes,retryIntervalMinutes:scheduleForm.retryIntervalMinutes,timeoutMinutes:scheduleForm.timeoutMinutes,upstreamFileIds:[...scheduleForm.upstreamFileIds]};scheduleSaving.value=true;try{const saved=await developmentApi.saveSchedule(targetId,payload);targetSession.schedule=saved;targetSession.scheduleForm={...payload,upstreamFileIds:[...payload.upstreamFileIds]};if(file.value?.id===targetId){schedule.value=saved;fillSchedule(saved)}await refreshBundle(targetId);if(file.value?.id===targetId)saveCurrentSession();ElMessage.success(`调度已保存为 S${saved.currentVersion}，尚未发布`)}catch(e){ElMessage.error(msg(e))}finally{if(file.value?.id===targetId)scheduleSaving.value=false;else scheduleSaving.value=false}}
async function loadLineage(){const current=file.value;if(!current||!isSql.value)return;const targetId=current.id,targetSession=ensureSession(current),name=stripExt(current.name);try{const rows=await metadataApi.lineage(name);targetSession.lineage=rows;if(file.value?.id===targetId)lineage.value=rows}catch{targetSession.lineage=[];if(file.value?.id===targetId)lineage.value=[]}}
async function switchBottom(v:BottomPane){activeBottom.value=v;saveCurrentSession();if(v==='lineage')await loadLineage();if(v==='plan')await loadPlan();saveCurrentSession()}

function handleNew(command:string){if(command==='folder'){newFolder.name='';newFolder.parentId=undefined;newFolderOpen.value=true}else{newTask.name='';newTask.type='SQL';newTask.folderId=undefined;newTask.description='';newTask.configureSchedule=false;newTaskOpen.value=true}}
async function createFolder(){if(!projectId.value||!newFolder.name.trim())return;try{const created=await developmentApi.createFolder({projectId:projectId.value,parentId:newFolder.parentId,name:newFolder.name.trim()});newFolderOpen.value=false;expandedFolders.value=new Set([...expandedFolders.value,created.id]);await loadResources();ElMessage.success('文件夹已创建')}catch(e){ElMessage.error(msg(e))}}
async function createTask(){if(!projectId.value||!newTask.name.trim())return;try{const base=newTask.name.trim().replace(/\s+/g,'_').replace(/\.(sql|sh|py)$/i,'');const ext=extensionOf(newTask.type);const name=base+ext;const created=await developmentApi.createFile({projectId:projectId.value,folderId:newTask.folderId,name,fileType:newTask.type,content:defaultContent(newTask.type,base),description:newTask.description});if(newTask.folderId)expandedFolders.value=new Set([...expandedFolders.value,newTask.folderId]);newTaskOpen.value=false;await loadResources(created.id);if(newTask.configureSchedule&&newTask.type==='SQL')activeDock.value='schedule';ElMessage.success('开发任务已创建并打开')}catch(e){ElMessage.error(msg(e))}}
function resourceTarget(row:TreeRow):ResourceTarget{return row.kind==='file'?{kind:'file',id:row.id,name:row.name,folderId:row.file?.folderId}:{kind:'folder',id:row.id,name:row.name,parentId:row.folder?.parentId}}
async function resourceCommand(command:string,row:TreeRow){const target=resourceTarget(row);if(command==='rename')return renameResource(target);if(command==='move'){moveTarget.value=target;moveFolderId.value=target.kind==='file'?target.folderId:target.parentId;moveOpen.value=true;return}if(command==='delete')return deleteResource(target)}
async function renameResource(target:ResourceTarget){try{const r=await ElMessageBox.prompt(`请输入新的${target.kind==='folder'?'文件夹':'任务'}名称`,'重命名',{inputValue:target.kind==='file'?stripExt(target.name):target.name,confirmButtonText:'保存',cancelButtonText:'取消',inputPattern:/^[^\\/:*?"<>|]+$/,inputErrorMessage:'名称不合法'});if(target.kind==='folder'){const folder=folders.value.find(x=>x.id===target.id)!;await developmentApi.updateFolder(target.id,{name:r.value.trim(),parentId:folder.parentId,moveToRoot:!folder.parentId})}else{const detail=await developmentApi.getFile(target.id);const ext=detail.name.match(/\.(sql|sh|py)$/i)?.[0]||extensionOf(detail.fileType.toUpperCase());await developmentApi.saveFile(target.id,{content:detail.content,name:r.value.trim().replace(/\.(sql|sh|py)$/i,'')+ext,description:detail.description,folderId:detail.folderId,moveToRoot:!detail.folderId})}await loadResources();ElMessage.success('重命名成功')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}
async function confirmMove(){const target=moveTarget.value;if(!target)return;try{if(target.kind==='folder'){await developmentApi.updateFolder(target.id,{name:target.name,parentId:moveFolderId.value,moveToRoot:!moveFolderId.value})}else{const detail=await developmentApi.getFile(target.id);await developmentApi.saveFile(target.id,{content:detail.content,name:detail.name,description:detail.description,folderId:moveFolderId.value,moveToRoot:!moveFolderId.value})}moveOpen.value=false;await loadResources();ElMessage.success('移动成功')}catch(e){ElMessage.error(msg(e))}}
async function deleteResource(target:ResourceTarget){try{const tip=target.kind==='folder'?`确认删除空文件夹“${target.name}”？`:`确认删除开发任务“${target.name}”？删除后将进入回收箱。`;await ElMessageBox.confirm(tip,'删除确认',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});if(target.kind==='folder')await developmentApi.deleteFolder(target.id);else await developmentApi.deleteFile(target.id);if(target.kind==='file'){openFiles.value=openFiles.value.filter(x=>x.id!==target.id);if(file.value?.id===target.id){file.value=undefined;setEditorContent('// 请选择开发任务','SQL')}}await loadResources();ElMessage.success(target.kind==='file'?'已移入回收箱':'文件夹已删除')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}

async function openRecycleBin(){if(!projectId.value)return;try{recycledFiles.value=await developmentApi.recycleBin(projectId.value);recycleOpen.value=true}catch(e){ElMessage.error(msg(e))}}
async function restoreRecycled(row:RecycledDevFile){try{await developmentApi.restoreFile(row.id);await loadResources(row.id);recycledFiles.value=await developmentApi.recycleBin(projectId.value!);ElMessage.success(`已恢复 ${row.name}`)}catch(e){ElMessage.error(msg(e))}}
async function permanentlyDeleteRecycled(row:RecycledDevFile){try{await ElMessageBox.confirm(`彻底删除“${row.name}”后无法恢复，确认继续？`,'彻底删除',{type:'error',confirmButtonText:'彻底删除',cancelButtonText:'取消'});await developmentApi.permanentlyDeleteFile(row.id);recycledFiles.value=await developmentApi.recycleBin(projectId.value!);ElMessage.success('已彻底删除')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}

function openPublish(){if(!file.value)return;if(file.value.id<0){ElMessage.info('请先保存临时 SQL');void saveCode();return}publishRemark.value='统一发布代码与调度配置';publishOpen.value=true}
async function publishBundle(){const current=file.value;if(!current||current.id<0)return;const targetId=current.id,targetName=current.name,targetVersion=current.currentVersion,targetSchedule=sessions.get(targetId)?.bundle?.scheduleVersion||bundle.value?.scheduleVersion||0;try{const req=await releaseApi.request({resourceType:'DEVELOPMENT',resourceId:targetId,resourceName:targetName,requestedVersion:targetVersion,payload:{remark:publishRemark.value,scheduleVersion:targetSchedule}});publishOpen.value=false;if(req.status==='PENDING_APPROVAL')ElMessage.success('发布申请已提交，等待审批');else ElMessage.success('代码与调度已统一发布');if(file.value?.id===targetId)await loadTaskMeta();else await refreshBundle(targetId)}catch(e){ElMessage.error(msg(e))}}
async function openCompareCurrent(){const current=file.value,online=onlineRelease.value;if(!current||!online)return ElMessage.warning('当前没有线上版本可对比');compareLoading.value=true;try{const versions=await developmentApi.versions(current.id);compareSqlCurrent.value=editor.value?.getValue()||current.content||'';compareSqlOnline.value=versions.find(v=>v.versionNo===online.sqlVersion)?.content||'';compareScheduleCurrent.value={fileId:current.id,currentVersion:bundle.value?.scheduleVersion||0,publishedVersion:bundle.value?.publishedScheduleVersion||0,enabled:scheduleForm.enabled,cycleType:scheduleForm.cycleType,executionTime:scheduleForm.executionTime,cronExpression:scheduleForm.cronExpression,timezone:scheduleForm.timezone,dataSourceId:scheduleForm.dataSourceId,databaseName:scheduleForm.databaseName,bizDateParam:scheduleForm.bizDateParam,retryTimes:scheduleForm.retryTimes,retryIntervalMinutes:scheduleForm.retryIntervalMinutes,timeoutMinutes:scheduleForm.timeoutMinutes,dependencies:scheduleDependencies.value,downstream:scheduleDownstream.value,publishedSqlVersion:bundle.value?.publishedSqlVersion||0,currentReleaseNo:bundle.value?.releaseNo||0};compareScheduleOnline.value=online.scheduleVersion>0?await developmentApi.scheduleVersion(current.id,online.scheduleVersion):undefined;compareTab.value='code';compareOpen.value=true}catch(e){ElMessage.error(msg(e))}finally{compareLoading.value=false}}
async function mountCompareEditor(){if(!compareEditorHost.value)return;monacoApi??=await import('monaco-editor/esm/vs/editor/editor.api');disposeCompareEditor();compareOriginalModel=monacoApi.editor.createModel(compareSqlOnline.value,'sql');compareModifiedModel=monacoApi.editor.createModel(compareSqlCurrent.value,'sql');compareDiffEditor.value=monacoApi.editor.createDiffEditor(compareEditorHost.value,{automaticLayout:true,readOnly:true,originalEditable:false,renderSideBySide:true,minimap:{enabled:false},fontSize:12,lineHeight:20,scrollBeyondLastLine:false});compareDiffEditor.value.setModel({original:compareOriginalModel,modified:compareModifiedModel})}
function disposeCompareEditor(){compareDiffEditor.value?.dispose();compareDiffEditor.value=undefined;compareOriginalModel?.dispose();compareModifiedModel?.dispose();compareOriginalModel=undefined;compareModifiedModel=undefined}
function showRelease(r:DevelopmentBundleRelease){selectedRelease.value=r;releaseDetailOpen.value=true}
async function rollbackRelease(){if(!file.value||!selectedRelease.value)return;try{await ElMessageBox.confirm(`确认将生产整体回滚到 P${selectedRelease.value.releaseNo}？代码与调度会一起回滚。`,'整体回滚',{type:'warning'});await developmentApi.rollbackBundle(file.value.id,selectedRelease.value.releaseNo);releaseDetailOpen.value=false;await loadTaskMeta();ElMessage.success(`已回滚到 P${selectedRelease.value.releaseNo}`)}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}
async function closeTab(tab:DevFile,e:Event){e.stopPropagation();if(tab.id===file.value?.id)saveCurrentSession();if(sessionDirty(tab.id)){try{await ElMessageBox.confirm('当前窗口有未保存修改，确认关闭？','关闭窗口',{type:'warning'})}catch{return}}const idx=openFiles.value.findIndex(x=>x.id===tab.id);openFiles.value.splice(idx,1);sessions.delete(tab.id);if(tab.id===file.value?.id){const next=openFiles.value[Math.max(0,idx-1)];if(next)await openFile(next);else{file.value=undefined;codeDirty.value=false;result.value=undefined;activeDock.value=null;setEditorContent('// 请选择开发任务','SQL')}}}

onMounted(boot);onBeforeUnmount(()=>{editor.value?.dispose();disposeCompareEditor()})
</script>

<template>
<div class="dev-ide"><div class="workbench">
  <aside class="sidebar">
    <div class="side-head"><strong>开发目录</strong><el-dropdown trigger="click" @command="handleNew"><el-button type="primary" size="small" :icon="Plus">新建</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="folder"><span class="new-folder-mini"></span>文件夹</el-dropdown-item><el-dropdown-item command="task"><span class="new-task-mini">+</span>开发任务</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div>
    <div class="side-search"><el-input v-model="treeSearch" size="small" placeholder="搜索开发任务..." :prefix-icon="Search" clearable/></div>
    <div class="group-switch"><button v-for="x in [{k:'all',n:'全部'},{k:'recent',n:'最近打开'},{k:'mine',n:'我的任务'}]" :key="x.k" :class="['pill',{active:groupMode===x.k}]" @click="groupMode=x.k as any">{{x.n}}</button></div>
    <div class="tree">
      <div v-for="row in treeRows" :key="row.kind+'-'+row.id" class="tree-row" :class="[{selected:row.kind==='file'&&file?.id===row.id},row.kind]" :style="{paddingLeft:(8+row.depth*18)+'px'}" @click="row.kind==='folder'?toggleFolder(row.id):openFile(row.file!)">
        <span v-if="row.kind==='folder'" :class="['tree-chevron',{expanded:folderExpanded(row.id)}]"></span><span v-if="row.kind==='folder'" :class="['folder-solid',{open:folderExpanded(row.id)}]"></span><span v-else class="file-ico" :class="(row.file?.fileType||'SQL').toLowerCase()">{{fileTypeText(row.file?.fileType)}}</span><span class="resource-name">{{row.kind==='file'?stripExt(row.name):row.name}}</span><span v-if="row.kind==='file'" :class="['task-state',stateClass(row.file!)]"></span>
        <el-dropdown trigger="click" @command="(c:string)=>resourceCommand(c,row)" @click.stop><button class="resource-more" @click.stop><el-icon><MoreFilled/></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item command="rename">重命名</el-dropdown-item><el-dropdown-item command="move">移动</el-dropdown-item><el-dropdown-item divided command="delete" :disabled="row.kind==='file'&&fileDeleteProtected(row.file)"><span :class="{'danger-text':!(row.kind==='file'&&fileDeleteProtected(row.file))}">{{row.kind==='file'&&fileDeleteProtected(row.file)?'已发布，禁止删除':'删除'}}</span></el-dropdown-item></el-dropdown-menu></template></el-dropdown>
      </div>
      <div v-if="!treeRows.length" class="tree-empty">暂无开发任务</div>
    </div><div class="side-foot"><span>生产空间</span><button class="recycle-entry" @click="openRecycleBin">回收箱 <b v-if="recycledFiles.length">{{recycledFiles.length}}</b></button></div>
  </aside>

  <main class="center">
    <div class="tabs"><button v-for="tab in openFiles" :key="tab.id" :class="['tab',{active:file?.id===tab.id,dirty:sessionDirty(tab.id)||(file?.id===tab.id&&codeDirty)}]" @click="openFile(tab)"><span class="dot"></span><span>{{tab.name}}</span><el-icon class="close" @click="closeTab(tab,$event)"><Close/></el-icon></button><button class="plus" title="新建临时 SQL" @click="newSqlDraft">＋</button></div>
    <div class="toolbar"><div class="meta"><span class="title">{{currentName}}</span><span class="badge dev">开发 V{{file?.currentVersion||0}}</span><span class="badge prod">生产 P{{bundle?.releaseNo||0}}</span><span :class="['badge',unsaved?'dirty':'prod']">{{unsaved?'● 有未发布变更':'✓ 已发布'}}</span></div><div class="actions"><el-button size="small" :loading="saving" @click="saveCode">保存 <span class="shortcut">Ctrl+S</span></el-button><el-button size="small" class="run" :loading="running" @click="runCode">▶ 运行 <span class="shortcut">Ctrl+Enter</span></el-button><el-button size="small" @click="formatCode">格式化</el-button><el-button size="small" type="primary" @click="openPublish">提交发布</el-button></div></div>

    <div class="middle"><div class="editor"><div ref="editorHost" class="editor-host"></div><div v-if="editorLoading&&!editor" class="editor-loading">正在加载编辑器…</div></div><div class="inspector-wrap">
      <section class="drawer" :class="{open:activeDock}"><div class="drawer-head"><strong>{{activeDock==='property'?'任务属性':activeDock==='schedule'?'调度配置':'版本管理'}}</strong><button class="x" @click="closeDock">×</button></div><div class="drawer-body">
        <div v-if="activeDock==='property'"><div class="section"><div class="section-title">基本属性</div><dl class="kv"><dt>任务名称</dt><dd>{{currentName}}</dd><dt>任务类型</dt><dd>{{currentTypeLabel}}</dd><dt>负责人</dt><dd>{{projects.find(x=>x.id===projectId)?.ownerName||'admin'}}</dd><dt>开发版本</dt><dd>V{{file?.currentVersion||0}}</dd><dt>生产版本</dt><dd>P{{bundle?.releaseNo||0}}</dd><dt>更新时间</dt><dd>{{fmt(file?.updatedAt)}}</dd></dl></div><div class="divider"></div><div class="form"><label>任务描述</label><textarea v-model="propertyDescription" @change="saveProperty"></textarea></div><div class="section"><div class="section-title">运行参数</div><div class="dep-item"><span>biz_date</span><span>{{isSql?scheduleForm.bizDateParam:'—'}}</span></div></div></div>
        <div v-else-if="activeDock==='schedule'"><template v-if="isSql"><div class="section"><div class="section-title">运行环境 <span class="help">真实 StarRocks 配置</span></div><div class="form"><label>StarRocks 数据源</label><el-select v-model="scheduleForm.dataSourceId" filterable @change="onScheduleSourceChange"><el-option v-for="s in sources" :key="s.id" :label="s.name" :value="s.id"/></el-select></div><div class="form"><label>Database</label><el-select v-model="scheduleForm.databaseName" filterable><el-option v-for="d in databases" :key="d" :label="d" :value="d"/></el-select></div></div><div class="divider"></div><div class="section"><div class="section-title">基本调度 <span class="help">修改后需重新发布</span></div><div class="form"><label>调度状态</label><el-select v-model="scheduleForm.enabled"><el-option label="已启用" :value="true"/><el-option label="已停用" :value="false"/></el-select></div><div class="two"><div class="form"><label>调度周期</label><el-select v-model="scheduleForm.cycleType" @change="syncCron"><el-option label="每日" value="DAILY"/><el-option label="每小时" value="HOURLY"/><el-option label="每周" value="WEEKLY"/><el-option label="每月" value="MONTHLY"/><el-option label="自定义 Cron" value="CRON"/></el-select></div><div v-if="scheduleForm.cycleType==='HOURLY'" class="form"><label>每小时第几分钟执行</label><el-select v-model="scheduleForm.hourMinute" filterable @change="syncCron"><el-option v-for="m in minuteOptions" :key="m" :label="`第 ${m} 分钟`" :value="m"/></el-select></div><div v-else class="form"><label>执行时间</label><el-time-picker v-model="scheduleForm.executionTime" value-format="HH:mm" format="HH:mm" style="width:100%" @change="syncCron"/></div></div><div class="form"><label>{{scheduleForm.cycleType==='CRON'?'Cron 表达式':'生成的 Cron'}}</label><el-input v-model="scheduleForm.cronExpression" :readonly="scheduleForm.cycleType!=='CRON'"/></div><div class="form"><label>时区</label><el-select v-model="scheduleForm.timezone"><el-option label="Asia/Shanghai" value="Asia/Shanghai"/><el-option label="UTC" value="UTC"/></el-select></div></div><div class="divider"></div><div class="section"><div class="section-title">上游依赖 <span class="help">成功后执行</span></div><el-select v-model="scheduleForm.upstreamFileIds" multiple filterable collapse-tags style="width:100%" placeholder="选择上游任务"><el-option v-for="f in upstreamOptions" :key="f.id" :label="stripExt(f.name)" :value="f.id"/></el-select><div class="dep-list"><div v-for="d in scheduleDependencies" :key="d.fileId" class="dep-item"><span>{{stripExt(d.name)}}</span><span>成功后执行</span></div><div v-if="!scheduleDependencies.length" class="dep-empty">暂无已保存上游依赖</div></div></div><div class="divider"></div><div class="section"><div class="section-title">运行参数</div><div class="form"><label>biz_date</label><el-select v-model="scheduleForm.bizDateParam"><el-option label="${system.biz.date-1}" value="${system.biz.date-1}"/><el-option label="${system.biz.date}" value="${system.biz.date}"/><el-option label="${system.date}" value="${system.date}"/></el-select></div></div><div class="divider"></div><div class="section"><div class="section-title">失败策略</div><div class="two"><div class="form"><label>失败重试次数</label><el-input-number v-model="scheduleForm.retryTimes" :min="0" :max="20"/></div><div class="form"><label>重试间隔（分钟）</label><el-input-number v-model="scheduleForm.retryIntervalMinutes" :min="1" :max="1440"/></div></div><div class="form"><label>任务超时（分钟）</label><el-input-number v-model="scheduleForm.timeoutMinutes" :min="1" :max="10080"/></div></div></template><el-empty v-else :description="`${currentTypeLabel} 任务执行引擎尚未接入，暂不支持生产调度`"/></div>
        <div v-else-if="activeDock==='version'"><div class="section-title"><span>发布版本 <span class="help">代码 + 调度统一发布</span></span><el-button v-if="onlineRelease" link type="primary" size="small" :loading="compareLoading" @click="openCompareCurrent">对比当前与线上</el-button></div><div v-if="unsaved" class="version-card current"><div class="vh"><b>待发布 · 开发中</b><small>当前</small></div><div class="version-inline"><span><em>代码</em> V{{file?.currentVersion||0}}</span><span><em>调度</em> S{{bundle?.scheduleVersion||0}}</span><span><em>状态</em> 未发布</span></div><div v-if="onlineRelease" class="version-compare"><strong>与线上 P{{onlineRelease.releaseNo}} 对比</strong><span :class="['compare-chip',{diff:(file?.currentVersion||0)!==onlineRelease.sqlVersion}]">代码 {{(file?.currentVersion||0)===onlineRelease.sqlVersion?'一致':`V${file?.currentVersion||0} → V${onlineRelease.sqlVersion}`}}</span><span :class="['compare-chip',{diff:(bundle?.scheduleVersion||0)!==onlineRelease.scheduleVersion}]">调度 {{(bundle?.scheduleVersion||0)===onlineRelease.scheduleVersion?'一致':`S${bundle?.scheduleVersion||0} → S${onlineRelease.scheduleVersion}`}}</span></div><div class="version-actions"><span v-if="onlineRelease" class="link" @click="openCompareCurrent">对比当前与线上</span><span class="link" @click="openPublish">提交发布</span></div></div><div v-for="r in releases" :key="r.releaseNo" class="version-card" :class="{current:r.current}"><div class="vh"><b>P{{r.releaseNo}} {{r.current?'· 当前生产':''}}</b><small>{{fmt(r.releasedAt)}}</small></div><div class="version-inline"><span><em>代码</em> V{{r.sqlVersion}}</span><span><em>调度</em> S{{r.scheduleVersion}}</span><span><em>发布人</em> {{r.operatorName}}</span></div><div v-if="onlineRelease" class="version-compare"><strong>{{r.current?'当前线上版本':`与线上 P${onlineRelease.releaseNo} 对比`}}</strong><template v-if="!r.current"><span :class="['compare-chip',{diff:r.sqlVersion!==onlineRelease.sqlVersion}]">代码 {{r.sqlVersion===onlineRelease.sqlVersion?'一致':`V${r.sqlVersion} → V${onlineRelease.sqlVersion}`}}</span><span :class="['compare-chip',{diff:r.scheduleVersion!==onlineRelease.scheduleVersion}]">调度 {{r.scheduleVersion===onlineRelease.scheduleVersion?'一致':`S${r.scheduleVersion} → S${onlineRelease.scheduleVersion}`}}</span></template><span v-else class="compare-chip">代码、调度均为当前线上</span></div><div class="version-actions"><span class="link" @click="showRelease(r)">查看详情</span><span v-if="!r.current" class="link" @click="selectedRelease=r;rollbackRelease()">回滚</span></div></div><el-empty v-if="!releases.length&&!unsaved" description="暂无发布版本"/></div>
      </div><div v-if="activeDock==='schedule'&&isSql" class="drawer-foot"><el-button size="small" @click="closeDock">取消</el-button><el-button size="small" type="primary" :loading="scheduleSaving" @click="saveSchedule">保存调度配置</el-button></div></section>
      <nav class="dock"><button :class="['dock-btn',{active:activeDock==='property'}]" @click="toggleDock('property')">属性</button><button :class="['dock-btn',{active:activeDock==='schedule'}]" @click="toggleDock('schedule')">调度</button><button :class="['dock-btn',{active:activeDock==='version'}]" @click="toggleDock('version')">版本</button><div class="dock-spacer"></div></nav>
    </div></div>

    <section class="bottom"><div class="bottom-tabs"><div class="btabs"><button v-for="x in [{k:'result',n:'运行结果'},{k:'log',n:'执行日志'},{k:'plan',n:'执行计划'},{k:'lineage',n:'数据血缘'},{k:'scheduleDag',n:'调度依赖'}]" :key="x.k" :class="['btab',{active:activeBottom===x.k}]" @click="switchBottom(x.k as BottomPane)">{{x.n}}</button></div><div class="runstatus">{{result?.status==='SUCCESS'?`✓ 最近执行成功 · ${result.elapsedMs} ms · ${result.rowCount} 行`:'运行任务后查看结果'}}</div></div><div class="panel"><div v-if="activeBottom==='result'"><el-table v-if="result?.rows?.length" :data="result.rows" height="180" size="small"><el-table-column v-for="c in result.columns" :key="c" :prop="c" :label="c" min-width="130"/></el-table><div v-else class="empty">暂无运行结果</div></div><pre v-else-if="activeBottom==='log'" class="log">{{logText}}</pre><pre v-else-if="activeBottom==='plan'" class="plan">{{planText}}</pre><div v-else-if="activeBottom==='lineage'" class="dag"><template v-if="lineage.length"><div v-for="x in lineage" :key="x.id" class="lineage-item"><div class="node"><b>{{x.sourceTable}}</b><span>数据表</span></div><div class="arrow">→</div><div class="node focus"><b>{{x.targetTable}}</b><span>当前产出表</span></div></div></template><div v-else class="empty">暂无数据血缘</div></div><div v-else class="dag"><div v-if="scheduleDependencies.length" class="dag-col"><div v-for="d in scheduleDependencies" :key="d.fileId" class="node"><b>{{stripExt(d.name)}}</b><span>上游任务 · 成功后执行</span></div></div><div v-if="scheduleDependencies.length" class="arrow">→</div><div class="node focus"><b>{{currentName}}</b><span>当前任务 · {{cycleLabel(schedule?.cycleType||'DAILY')}} {{schedule?.executionTime||'—'}}</span></div><div v-if="scheduleDownstream.length" class="arrow">→</div><div v-if="scheduleDownstream.length" class="dag-col"><div v-for="d in scheduleDownstream" :key="d.fileId" class="node"><b>{{stripExt(d.name)}}</b><span>下游任务</span></div></div></div></div></section>
    <div class="statusbar"><div><span><span class="gdot" :class="{muted:!isSql}"></span>{{isSql?'StarRocks 已连接':'本地开发任务'}}</span><span>{{isSql?currentSourceName:'生产空间'}}</span><span>{{isSql?(database||'—'):currentTypeLabel}}</span></div><div><span>UTF-8</span><span>{{currentTypeLabel}}</span><span>自动保存：关闭</span></div></div>
  </main>
</div>

<el-dialog v-model="saveDraftOpen" title="保存 SQL" width="480px"><el-form label-position="top"><el-form-item label="文件名称 *"><el-input v-model="saveDraft.name" placeholder="请输入 SQL 文件名称"><template #append>.sql</template></el-input></el-form-item><el-form-item label="保存位置"><el-select v-model="saveDraft.folderId" clearable filterable placeholder="根目录" style="width:100%"><el-option v-for="x in folderOptions" :key="x.id" :label="x.label" :value="x.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="saveDraftOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="confirmSaveDraft">保存</el-button></template></el-dialog>
<el-dialog v-model="newFolderOpen" title="新建文件夹" width="460px"><el-form label-position="top"><el-form-item label="文件夹名称 *"><el-input v-model="newFolder.name" placeholder="请输入文件夹名称"/></el-form-item><el-form-item label="上级文件夹"><el-select v-model="newFolder.parentId" clearable filterable placeholder="根目录"><el-option v-for="x in folderOptions" :key="x.id" :label="x.label" :value="x.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="newFolderOpen=false">取消</el-button><el-button type="primary" @click="createFolder">创建</el-button></template></el-dialog>
<el-dialog v-model="newTaskOpen" title="新建开发任务" width="560px"><el-form label-position="top"><div class="dialog-grid"><el-form-item label="任务名称 *"><el-input v-model="newTask.name" placeholder="例如：dwd_order_detail"/></el-form-item><el-form-item label="任务类型 *"><el-select v-model="newTask.type"><el-option label="SQL" value="SQL"/><el-option label="Shell" value="SHELL"/><el-option label="Python" value="PYTHON"/></el-select></el-form-item><el-form-item label="所属文件夹"><el-select v-model="newTask.folderId" clearable filterable placeholder="根目录"><el-option v-for="x in folderOptions" :key="x.id" :label="x.label" :value="x.id"/></el-select></el-form-item><el-form-item label="负责人"><el-input :model-value="projects.find(x=>x.id===projectId)?.ownerName||'admin'" disabled/></el-form-item></div><el-form-item label="任务描述"><el-input v-model="newTask.description" type="textarea"/></el-form-item><el-checkbox v-model="newTask.configureSchedule" :disabled="newTask.type!=='SQL'">创建后打开调度配置</el-checkbox></el-form><template #footer><el-button @click="newTaskOpen=false">取消</el-button><el-button type="primary" @click="createTask">创建并打开</el-button></template></el-dialog>
<el-dialog v-model="moveOpen" :title="`移动${moveTarget?.kind==='folder'?'文件夹':'开发任务'}`" width="480px"><el-form label-position="top"><el-form-item label="目标文件夹"><el-select v-model="moveFolderId" clearable filterable placeholder="根目录"><el-option v-for="x in moveFolderOptions" :key="x.id" :label="x.label" :value="x.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="moveOpen=false">取消</el-button><el-button type="primary" @click="confirmMove">移动</el-button></template></el-dialog>

<el-dialog v-model="recycleOpen" title="回收箱" width="760px"><div class="recycle-tip">删除的未发布开发任务会保留在这里；已发布任务禁止删除。</div><el-table :data="recycledFiles" size="small" max-height="430"><el-table-column prop="name" label="文件" min-width="180"><template #default="{row}"><span class="recycle-file-type">{{fileTypeText(row.fileType)}}</span>{{row.name}}</template></el-table-column><el-table-column label="原目录" min-width="120"><template #default="{row}">{{row.folderName||'根目录'}}</template></el-table-column><el-table-column label="删除人" prop="recycledBy" width="100"/><el-table-column label="删除时间" width="170"><template #default="{row}">{{fmt(row.recycledAt)}}</template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="restoreRecycled(row)">恢复</el-button><el-button link type="danger" @click="permanentlyDeleteRecycled(row)">彻底删除</el-button></template></el-table-column></el-table><el-empty v-if="!recycledFiles.length" description="回收箱为空"/><template #footer><el-button @click="recycleOpen=false">关闭</el-button></template></el-dialog>
<el-dialog v-model="publishOpen" title="提交发布" width="820px"><div class="release-strip"><strong>P{{(bundle?.releaseNo||0)+1}}</strong><span>=</span><span>开发 V{{file?.currentVersion||0}}</span><span>+</span><span>调度 S{{bundle?.scheduleVersion||0}}</span><span class="push-right">当前生产 P{{bundle?.releaseNo||0}}</span></div><el-form label-position="top"><div class="dialog-grid"><el-form-item label="任务名称"><el-input :model-value="currentName" disabled/></el-form-item><el-form-item label="变更说明 *"><el-input v-model="publishRemark"/></el-form-item></div></el-form><div class="check-title">发布前检查</div><div class="checks"><div><span>代码已保存</span><b class="ok">{{codeDirty?'需先保存':'✓ 通过'}}</b></div><div v-if="isSql"><span>StarRocks 数据源</span><b class="ok">{{scheduleForm.dataSourceId?'✓ 已配置':'未配置'}}</b></div><div><span>任务权限</span><b class="ok">✓ 通过</b></div></div><template #footer><el-button @click="publishOpen=false">取消</el-button><el-button type="primary" :disabled="codeDirty" @click="publishBundle">确认发布</el-button></template></el-dialog>
<el-dialog v-model="compareOpen" :title="`当前开发 vs 线上 P${onlineRelease?.releaseNo||''}`" width="1080px" top="6vh" @opened="mountCompareEditor" @closed="disposeCompareEditor"><div class="compare-summary"><span>当前开发 V{{file?.currentVersion||0}}{{codeDirty?'（含未保存内容）':''}}</span><span>线上 P{{onlineRelease?.releaseNo||0}} · V{{onlineRelease?.sqlVersion||0}} / S{{onlineRelease?.scheduleVersion||0}}</span><el-tag size="small" :type="compareSqlChanged?'warning':'success'">代码{{compareSqlChanged?'有差异':'一致'}}</el-tag><el-tag size="small" :type="compareScheduleRows.some(x=>x.changed)?'warning':'success'">调度{{compareScheduleRows.some(x=>x.changed)?'有差异':'一致'}}</el-tag></div><el-tabs v-model="compareTab" class="compare-tabs"><el-tab-pane name="code" label="代码对比"><div class="compare-code-head"><span>线上 V{{onlineRelease?.sqlVersion||0}}</span><span>当前开发 V{{file?.currentVersion||0}}{{codeDirty?'（含未保存）':''}}</span></div><div ref="compareEditorHost" class="compare-editor"></div></el-tab-pane><el-tab-pane name="schedule" label="调度对比"><el-table :data="compareScheduleRows" size="small" max-height="480"><el-table-column prop="name" label="配置项" width="150"/><el-table-column prop="current" label="当前开发" min-width="250"/><el-table-column prop="online" label="当前线上" min-width="250"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag size="small" :type="row.changed?'warning':'success'">{{row.changed?'有差异':'一致'}}</el-tag></template></el-table-column></el-table></el-tab-pane></el-tabs><template #footer><el-button @click="compareOpen=false">关闭</el-button></template></el-dialog>
<el-dialog v-model="releaseDetailOpen" :title="`发布版本 P${selectedRelease?.releaseNo||''}`" width="680px"><div v-if="selectedRelease" class="release-strip"><strong>P{{selectedRelease.releaseNo}}</strong><span>开发 V{{selectedRelease.sqlVersion}} + 调度 S{{selectedRelease.scheduleVersion}}</span><span class="push-right">{{selectedRelease.current?'当前生产':'历史'}}</span></div><div v-if="selectedRelease" class="change-grid release-detail"><div><b>代码版本</b><p>V{{selectedRelease.sqlVersion}}</p></div><div><b>调度配置</b><p>S{{selectedRelease.scheduleVersion}}</p><p>{{selectedRelease.remark||'统一发布'}}</p></div></div><template #footer><el-button @click="releaseDetailOpen=false">关闭</el-button><el-button v-if="selectedRelease&&!selectedRelease.current" type="primary" @click="rollbackRelease">回滚到此发布版本</el-button></template></el-dialog>
</div>
</template>

